"""Shell-textured hair: stacked offset layers of the scalp with a strand texture generated by
line-integral convolution along a combing flow field. Outputs hair_shells.npz + hair_shell.png (RGBA, 2048)."""
import numpy as np, cv2

T = 2048; K = 6
rng = np.random.default_rng(3)
m = np.load("base_mesh.npz"); F = m["F"]; FL = m["FL"]; UV = m["uv"]; body = m["g_body"]
FIT = __import__("os").environ.get("FIT", "fit2_result.npz")
FR = np.load(FIT); V = FR["Vfit"]; vid = np.load("corr.npz")["vid"]
hp4 = cv2.imread("hairprob_4k.png", 0).astype(np.float32) / 255
hp_img = cv2.resize(hp4, (T, T), interpolation=cv2.INTER_AREA)
photo = cv2.resize(cv2.imread("skin_4k.png"), (T, T), interpolation=cv2.INTER_AREA).astype(np.float32)

inb = np.zeros(len(V), bool); inb[body] = True
Fb, FLb = F[inb[F].all(1)], FL[inb[F].all(1)]
px = lambda uv: np.stack([uv[..., 0] * T, (1 - uv[..., 1]) * T], -1)
uvpx = px(UV)
xi = np.clip(uvpx[:, 0].astype(int), 0, T - 1); yi = np.clip(uvpx[:, 1].astype(int), 0, T - 1)
hp_loop = hp_img[yi, xi]
hp_v = np.zeros(len(V)); np.maximum.at(hp_v, Fb.ravel(), hp_loop[FLb.ravel()])

z_forehead = V[vid[10], 2]; z_lobe = V[vid[177], 2] - 0.01; top = V[body, 2].max(); y_ear = V[vid[234], 1]
ear_top_z = V[vid[127], 2] + 0.01
cand = (V[:, 2] > z_lobe - 0.02) | ((V[:, 1] > y_ear + 0.02) & (V[:, 2] > z_lobe - 0.07))
face_front = (V[:, 1] < y_ear - 0.015) & (V[:, 2] < z_forehead - 0.012)
topz = inb & (V[:, 2] > z_forehead - 0.006) & (V[:, 1] > V[vid[10], 1] - 0.006) & (np.abs(V[:, 0]) < 0.056)
keep_v = (inb & cand & (~face_front | (hp_v > 0.45)) & (hp_v > 0.2)) | topz
fm = keep_v[Fb].all(1) & ((hp_loop[FLb].mean(1) > 0.25) | topz[Fb].all(1))
Fc, FLc = Fb[fm], FLb[fm]
print("scalp tris", len(Fc))

vn = np.zeros_like(V)
fn = np.cross(V[Fb[:, 1]] - V[Fb[:, 0]], V[Fb[:, 2]] - V[Fb[:, 0]])
for j in range(3): np.add.at(vn, Fb[:, j], fn)
vn /= np.linalg.norm(vn, axis=1, keepdims=True) + 1e-12

# ---- combing flow (3D, per vertex) ----
def flow(P, N):
    s = np.clip((P[:, 2] - ear_top_z) / 0.05, 0, 1); s = s * s * (3 - 2 * s)        # 0 sides/back, 1 top
    down_back = np.stack([np.zeros(len(P)), 0.45 * np.ones(len(P)), -np.ones(len(P))], 1)
    back = np.stack([0.25 * np.tanh(P[:, 0] / 0.03), np.ones(len(P)), 0.15 * np.ones(len(P))], 1)
    d = down_back * (1 - s[:, None]) + back * s[:, None]
    d -= N * (d * N).sum(1, keepdims=True)
    return d / (np.linalg.norm(d, axis=1, keepdims=True) + 1e-12)
D3 = flow(V, vn)

# ---- rasterise UV-space flow direction for the scalp triangles ----
DIR = np.zeros((T, T, 2), np.float32); MASK = np.zeros((T, T), np.float32)
for f, fl in zip(Fc, FLc):
    q = uvpx[fl]; P = V[f]
    A = np.stack([P[1] - P[0], P[2] - P[0]], 1)          # 3x2
    B = np.stack([q[1] - q[0], q[2] - q[0]], 1)          # 2x2
    J = B @ np.linalg.pinv(A)                            # 2x3: dUV = J dP
    d = J @ D3[f].mean(0); d /= np.linalg.norm(d) + 1e-12
    x0, y0 = np.floor(q.min(0)).astype(int); x1, y1 = np.ceil(q.max(0)).astype(int)
    xs, ys = np.meshgrid(np.arange(x0, x1 + 1), np.arange(y0, y1 + 1))
    a, b, c = q
    den = (b[1] - c[1]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[1] - c[1])
    if abs(den) < 1e-9: continue
    l1 = ((b[1] - c[1]) * (xs + .5 - c[0]) + (c[0] - b[0]) * (ys + .5 - c[1])) / den
    l2 = ((c[1] - a[1]) * (xs + .5 - c[0]) + (a[0] - c[0]) * (ys + .5 - c[1])) / den
    ok = (l1 >= -0.05) & (l2 >= -0.05) & (1 - l1 - l2 >= -0.05)
    yy, xx = np.clip(ys[ok], 0, T - 1), np.clip(xs[ok], 0, T - 1)
    DIR[yy, xx] = d; MASK[yy, xx] = 1
# smooth the direction field (avoid per-triangle steps) and extend it a bit beyond the island
for _ in range(3):
    DIR = cv2.GaussianBlur(DIR, (0, 0), 6) / np.maximum(cv2.GaussianBlur(MASK, (0, 0), 6), 1e-6)[..., None]
DIR /= np.linalg.norm(DIR, axis=2, keepdims=True) + 1e-9

# ---- LIC strand noise ----
def lic(noise, L=28, step=1.0):
    H, W = noise.shape
    gx, gy = np.meshgrid(np.arange(W, dtype=np.float32), np.arange(H, dtype=np.float32))
    acc = noise.copy(); wsum = np.ones_like(noise)
    for sgn in (1, -1):
        x, y = gx.copy(), gy.copy()
        for k in range(1, L):
            d = cv2.remap(DIR, x, y, cv2.INTER_LINEAR)
            x = x + sgn * step * d[..., 0]; y = y + sgn * step * d[..., 1]
            w = 1 - k / L
            acc += w * cv2.remap(noise, x, y, cv2.INTER_LINEAR); wsum += w
    return acc / wsum
fine = lic(rng.random((T, T)).astype(np.float32), L=30)
clump = lic(cv2.GaussianBlur(rng.random((T, T)).astype(np.float32), (0, 0), 3), L=40)
norm = lambda a: (a - a[MASK > 0].mean()) / (a[MASK > 0].std() + 1e-6)
strand = 0.5 + 0.10 * norm(fine) + 0.12 * norm(clump)
strand = np.clip(strand, 0, 1)

# coverage: photo hair probability; thinner on the very top-front (scalp shows through)
cov = cv2.GaussianBlur(hp_img, (0, 0), 2)
# guaranteed density on the top/back of the head (thin but present hair), keep the receding front edge from the photos
ZT = np.zeros((T, T), np.float32)
for f, fl in zip(Fc, FLc):
    q = uvpx[fl].astype(np.int32)
    zt = np.clip((V[f, 2].mean() - (z_forehead + 0.004)) / 0.03, 0, 1) * np.clip((V[f, 1].mean() - (V[vid[10], 1] + 0.004)) / 0.03, 0, 1) * np.clip(1.6 - abs(V[f, 0].mean()) / 0.035, 0, 1)
    back = np.clip((V[f, 1].mean() - (y_ear + 0.01)) / 0.03, 0, 1)
    cv2.fillConvexPoly(ZT, q, float(max(zt, back)))
ZT = cv2.GaussianBlur(ZT, (0, 0), 8)
cov = np.maximum(cov, 0.97 * ZT)
alpha = np.clip(cov * (0.78 + 0.6 * (strand - 0.5)), 0, 1) * (cov > 0.15)
# colour: photo hair colour (blurred), modulated by strands; strands lighter at tips/highlights
hpm = hp_img > 0.85
HC = np.array([34.0, 44.0, 60.0])   # BGR, median of the hair pixels in the well-lit photos
w_ph = (np.clip((hp_img - 0.7) / 0.25, 0, 1) * (1 - np.clip(ZT * 1.5 - 0.5, 0, 1)))[..., None]
ph_ = cv2.GaussianBlur(photo, (0, 0), 3); ph_ = ph_.mean(2, keepdims=True) + (ph_ - ph_.mean(2, keepdims=True)) * 0.6
base_col = ph_ * w_ph * 0.92 + HC * (1 - w_ph)
lab = cv2.cvtColor(np.clip(base_col, 0, 255).astype(np.uint8), cv2.COLOR_BGR2LAB).astype(np.float32)
lab[..., 0] = np.clip(lab[..., 0] * (0.72 + 0.45 * strand), 0, 255) * 0.9
col = cv2.cvtColor(lab.astype(np.uint8), cv2.COLOR_LAB2BGR)
import json as _j, os as _o
if False and _o.path.exists("calib.json"):
    _g = np.array(_j.load(open("calib.json"))["hair"])
    col = np.clip(255 * (((col.astype(np.float32) / 255) ** 2.2) * _g[None, None, :]) ** (1 / 2.2), 0, 255).astype(np.uint8)
cv2.imwrite("hair_shell.png", np.dstack([col, (alpha * 255).astype(np.uint8)]))
ys, xs = np.where(MASK > 0)
crop = np.dstack([col, (alpha * 255).astype(np.uint8)])[ys.min():ys.max(), xs.min():xs.max()]
prev = (crop[..., :3] * (crop[..., 3:] / 255) + 200 * (1 - crop[..., 3:] / 255)).astype(np.uint8)
cv2.imwrite("../shots/hair_shell_tex.jpg", cv2.resize(prev, None, fx=0.6, fy=0.6))

# ---- shells ----
uniq, inv = np.unique(Fc.ravel(), return_inverse=True)
P = V[uniq]; N = vn[uniq]
h = np.clip((P[:, 2] - (z_lobe + 0.03)) / (top - z_lobe - 0.03), 0, 1)
front_top = np.clip((y_ear + 0.01 - P[:, 1]) / 0.08, 0, 1) * h
Tk = 0.004 + 0.008 * h + 0.006 * front_top                       # total hair depth
edge = np.clip((hp_v[uniq] - 0.25) / 0.45, 0, 1); Tk *= 0.3 + 0.7 * edge * edge * (3 - 2 * edge)
# ---- visual-hull carving: max offset along the normal that stays inside the person silhouette in every view ----
from geom import rodrigues as _rod, project as _proj, load_seg as _ls
_cams = dict(zip(FR["vnames"], FR["cams"])); _fs = dict(zip(FR["vnames"], FR["fs"])) if "fs" in FR else {}
_cams["back"] = np.load("cam_back.npy")
_views = [v for v in ("front", "front_close", "three_quarter", "profile_right_side", "profile_left_side", "back", "p01", "p03", "p09", "p17") if v in _cams]
ts = np.linspace(0.0, 0.035, 36)
inside = np.ones((len(P), len(ts)), bool)
for vn_ in _views:
    segp = f"seg2_{vn_}.npy" if vn_[1:].isdigit() else f"seg_{vn_}.npy"
    fg = (1 - _ls(segp)[..., 0]) > 0.5
    fg = cv2.erode(fg.astype(np.uint8), np.ones((5, 5), np.uint8)) > 0
    c_ = _cams[vn_]; R_ = _rod(c_[:3]); f_ = _fs.get(vn_, float(FR["F_PX"]))
    for j, t_ in enumerate(ts):
        uv_, _ = _proj(P + N * t_, R_, c_[3:], f_, 1736, 2312)
        x_ = np.clip(uv_[:, 0].astype(int), 0, 3471); y_ = np.clip(uv_[:, 1].astype(int), 0, 4623)
        oob = (uv_[:, 0] < 0) | (uv_[:, 0] >= 3472) | (uv_[:, 1] < 0) | (uv_[:, 1] >= 4624)
        inside[:, j] &= fg[y_, x_] | oob
    print("   hull view", vn_)
first_out = np.where((~inside).any(1), (~inside).argmax(1), len(ts) - 1)
hull = ts[np.maximum(first_out - 1, 0)]
# smooth on the mesh (neighbour averaging over cap vertices)
nb = [[] for _ in range(len(P))]
for tri_ in inv.reshape(-1, 3):
    for a_ in tri_:
        nb[a_].extend(int(b) for b in tri_ if b != a_)
for _ in range(6):
    hull = np.array([0.5 * hull[i] + 0.5 * np.mean(hull[nb[i]]) if nb[i] else hull[i] for i in range(len(P))])
print("   hull depth mm p10/50/90", np.percentile(hull, [10, 50, 90]) * 1000)
Tk = np.clip(np.minimum(hull * 0.95, 0.03), 0.0015, None) * (0.3 + 0.7 * edge * edge * (3 - 2 * edge))
verts, faces, uvs, mats = [], [], [], []
tri = inv.reshape(-1, 3); uvl = UV[FLc].reshape(-1, 2)
for k in range(K):
    off = 0.0008 + Tk * (k / (K - 1))
    verts.append(P + N * off[:, None]); faces.append(tri + k * len(P)); uvs.append(uvl); mats.append(np.full(len(tri), k))
np.savez("hair_shells.npz", V=np.concatenate(verts), F=np.concatenate(faces), uv=np.concatenate(uvs),
         mat=np.concatenate(mats), src=np.tile(uniq, K), K=K)
print("shell verts", len(P) * K, "depth mm", Tk.min() * 1000, Tk.max() * 1000)
